import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {

}
<div class="home-container">
  <div class="text-section">
    <h1>Welcome to <span class="highlight">Ecomerce Online Marketplace</span></h1>
    <p>Buy and sell the best products from trusted vendors across the nation.</p>
    <button mat-raised-button color="primary" routerLink="/signup">Get Started</button>
  </div>
  <div class="image-section">
    <img src="assets/shopping-app.png" alt="Ecommerce Illustration" />
  </div>
</div>
